        val fndecls = toSet(index.functions.matchFirst(f)).asInstanceOf[Set[JavaFunctional]]
        val fndeclsfiltered = fndecls.filter(f => f.isInstanceOf[DeclaredFunction])
        toFunctionArrows(fndeclsfiltered, false)
    }    

